 "model": {
  "variables": [
   {
    "name": "toy cars",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "toy trucks",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "toy cars",
     "coef": 30.0
    },
    {
     "var": "toy trucks",
     "coef": 35.0
    }
   ]
  },
  "constraints": [
   {
